const test = require('node:test');
const assert = require('node:assert/strict');
const { summary } = require('../museum/service.cjs');
test('the mean divides the total by the number of open days', () => {
  const counts = Object.freeze([12,18]);
  assert.equal(summary(counts),'Daily average: 15');
  assert.equal(summary([2,3,4]),'Daily average: 3');
  assert.equal(summary([1,2]),'Daily average: 1.5');
  assert.equal(summary([7]),'Daily average: 7');
  assert.equal(summary([0,0]),'Daily average: 0');
  assert.equal(summary([0,10]),'Daily average: 5');
  assert.equal(summary([]),'No open days');
});

